def _unwrap_init_var(annotation: Any) -> Any:
    """Unwrap InitVar[X] to X."""
    if (
        hasattr(annotation, "__origin__")
        and annotation.__origin__ is dataclasses.InitVar
    ):
        return annotation.__args__[0]
    return annotation

def autowire(fn_or_cls: Callable) -> Callable[[Container], Any]:
    if isgeneratorfunction(fn_or_cls):
        raise TypeError(f"autowire() cannot be used with bare generator functions: {fn_or_cls}")

    sig = _robust_signature(fn_or_cls)
    if sig is None:
        raise TypeError(f"Could not inspect signature of {fn_or_cls}")

    def factory(container: Container) -> Any:
        args = []
        for name, param in sig.parameters.items():
            if param.kind in (inspect.VAR_POSITIONAL, inspect.VAR_KEYWORD):
                continue

            annotation = _unwrap_init_var(param.annotation)

            if param.annotation is inspect.Parameter.empty and param.default is inspect.Parameter.empty:
                raise TypeError(f"Parameter {name} in {fn_or_cls} is required but has no annotation or default.")

            if param.annotation is inspect.Parameter.empty:
                continue

            if annotation is Container:
                args.append(container)
                continue

            try:
                args.append(container.get(annotation))
            except ServiceNotFoundError:
                if param.default is not inspect.Parameter.empty:
                    args.append(param.default)
                else:
                    raise

        return fn_or_cls(*args)

    return factory

